package com.nora.tunnel.data import android.content.Context import kotlinx.serialization.encodeToString import kotlinx.serialization.json.Json class BackupManager(private val context: Context, private val db: com.nora.tunnel.data.database.NoraDatabase) { suspend fun export(): String { val profiles = db.profileDao().observeAll() // Collect first // NEVER export secrets - export credentialRef only, secrets stay in EncryptedSharedPreferences return Json.encodeToString(profiles) } suspend fun import(json: String): ConfigParser.ParseResult { return try { ConfigParser.parse(json) } catch(e: Exception) { ConfigParser.ParseResult.Failure("import", e.message ?: "Invalid backup", "Check file") } } }
